			    util.DataSet.setValue(app, "dsList", 0, "CASE_MNG_ODRNO", poData2); //사례관리차수
			    var dmListParam = app.lookup("dmListParam");
			    dmListParam.setValue("CASE_MNG_NO", poData1);
			    dmListParam.setValue("CASE_MNG_ODRNO", poData2);

			    var dmCnctrClinicInfo = app.lookup("dmCnctrClinicInfo");
